#include "quake/frame3d.hpp"
#include "quake/ida.hpp"
#include <iomanip>
#include <iostream>
using namespace quake;
static int id(int s,int side){return 100*s+side;}
static CompiledFrame3D model(){Frame3DBuilder b;constexpr int N=4;constexpr double h=3.5,L=6,E=25000,G=10000;for(int s=0;s<=N;++s)for(int side=0;side<2;++side){double m=s?.5:0;b.add_node(id(s,side),side*L,0,s*h,m,m,.1*m);if(!s)b.fix(id(s,side));}int eid=1,hid=1;ASCE41HingeParams hp;hp.Ke=40000;hp.posFy=hp.negFy=7;hp.hardening_ratio=.02;hp.pos_a=hp.neg_a=.006;hp.pos_b=hp.neg_b=.035;hp.pos_f=hp.neg_f=.055;hp.pos_c=hp.neg_c=.2;hp.pos_drop_span=hp.neg_drop_span=.002;hp.pos_io=hp.neg_io=.002;hp.pos_ls=hp.neg_ls=.01;hp.pos_cp=hp.neg_cp=.02;hp.lambda_strength=.12;hp.lambda_unloading=.15;for(int s=1;s<=N;++s){double P=10*(N-s+1);for(int side=0;side<2;++side)b.add_elastic_frame(eid++,id(s-1,side),id(s,side),E,G,2,.3,.55,.55,1,0,0,P);int dl=10000+s*10,dr=dl+1;b.add_node(dl,0,0,s*h);b.add_node(dr,L,0,s*h);for(auto d:{Dof3D::UX,Dof3D::UY,Dof3D::UZ,Dof3D::RX,Dof3D::RZ}){b.equal_dof(id(s,0),dl,d);b.equal_dof(id(s,1),dr,d);}b.add_elastic_frame(eid++,dl,dr,E,G,1.5,.2,.35,.35,0,1,0);b.add_asce41_hinge(hid++,id(s,0),Dof3D::RY,dl,Dof3D::RY,hp);b.add_asce41_hinge(hid++,id(s,1),Dof3D::RY,dr,Dof3D::RY,hp);}b.set_rayleigh(.02,.0005);b.set_response(id(N,0),Dof3D::UX);std::vector<int> stories;for(int s=1;s<=N;++s)stories.push_back(id(s,0));b.set_story_nodes(stories,Dof3D::UX);return b.compile();}
static const char* cause(CollapseMechanism c){switch(c){case CollapseMechanism::TangentInstability:return "tangent";case CollapseMechanism::DriftLimit:return "drift";case CollapseMechanism::LateralResistanceLoss:return "E-loss";case CollapseMechanism::GravityResistanceLoss:return "F-loss";case CollapseMechanism::UnrecoverableLateralLoss:return "loss-equilibrium";case CollapseMechanism::NumericalFailure:return "numerical";case CollapseMechanism::InitialInstability:return "initial";case CollapseMechanism::BeyondCPConfigured:return "beyond-CP";default:return "none";}}
int main(int argc,char**argv){int workers=argc>1?std::stoi(argv[1]):4;auto m=model();double dt=.005;std::vector<GroundMotionRecord> recs;for(int i=0;i<8;++i)recs.push_back({"R"+std::to_string(i+1),synthetic_ground_motion(350,dt,.75+.07*i),dt});IDAOptions o;o.workers=workers;o.scale_factors={.5,1,2,3,4,6,8,10,14,18};o.collapse_refinement_steps=3;o.analysis.max_iterations=45;o.analysis.max_subdivisions=4;o.analysis.max_backtracks=10;o.analysis.nonmonotone_line_search_factor=1.08;o.analysis.return_numerical_failure=true;o.analysis.collapse.max_story_drift_ratio=.06;o.analysis.collapse.max_failed_components=2;o.analysis.collapse.tangent_check_interval=20;o.analysis.collapse.min_tangent_ratio=.02;o.analysis.collapse.classify_unrecoverable_lateral_loss_as_collapse=true;auto r=run_ida_suite(m,recs,o);std::cout<<std::fixed<<std::setprecision(5)<<"records="<<r.records.size()<<" runs="<<r.runs.size()<<" workers="<<r.workers<<" elapsed="<<r.elapsed_seconds<<" collapsed="<<r.physical_collapses<<" censored="<<r.right_censored_records<<" numerical="<<r.numerical_failures<<" median_collapse_PGA="<<r.collapse_pga_median<<" beta_ln="<<r.collapse_pga_log_stddev<<"\n";for(const auto& x:r.records)std::cout<<x.record_name<<" collapse="<<x.collapsed<<" scale="<<x.first_collapse_scale<<" pga="<<x.collapse_pga<<" cause="<<cause(x.collapse_mechanism)<<" bracket_low="<<x.last_noncollapse_scale<<"\n";}
